CREATE TRIGGER IF NOT EXISTS open_capacity_provider_insert AFTER INSERT ON open_provider_resources BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM open_capacity_policy WHERE singleton=1 AND schema_version='memory-vault-open-capacity/v1') THEN RAISE(ABORT,'open_capacity_binding_missing') END;
SELECT CASE WHEN typeof(NEW.retain_until)!='integer' OR NEW.retain_until<0 OR typeof(NEW.expires_at)!='integer' OR NEW.expires_at<0 OR length(NEW.lease_id) NOT BETWEEN 1 AND 128 OR length(NEW.owner) NOT BETWEEN 1 AND 128 OR length(NEW.allocation_id) NOT BETWEEN 1 AND 128 OR length(NEW.digest)!=64 OR NEW.digest GLOB '*[^0-9a-f]*' OR length(NEW.record)>8192 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN json_valid(CAST(NEW.record AS TEXT))!=1 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN typeof(json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes'))!='integer' OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')<0 OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')>9007199254740991 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN typeof(json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes'))!='integer' OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')<0 OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')>9007199254740991 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN typeof(json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes'))!='integer' OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')<0 OR json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')>9007199254740991 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
