SELECT CASE WHEN typeof(json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_replay_records')*32768+36864)!='integer' OR (json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_replay_records')*32768+36864)<1 OR (json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_replay_records')*32768+36864)>9007199254740991 OR typeof(NEW.retain_until)!='integer' OR NEW.retain_until<NEW.expires_at OR NEW.retain_until>9007199254740991 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
INSERT INTO open_capacity_reservations VALUES('provider',NEW.lease_id,NEW.digest,json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_live_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_meta_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_job_bytes')+json_extract(CAST(NEW.record AS TEXT),'$.payload.budget.max_replay_records')*32768+36864,NEW.retain_until,NEW.owner,NEW.allocation_id,NEW.root_digest);
