CREATE TRIGGER IF NOT EXISTS open_capacity_contact_insert AFTER INSERT ON open_contact_resource_leases BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM open_capacity_policy WHERE singleton=1 AND schema_version='memory-vault-open-capacity/v1') THEN RAISE(ABORT,'open_capacity_binding_missing') END;
SELECT CASE WHEN typeof(NEW.retain_until)!='integer' OR NEW.retain_until<0 OR typeof(NEW.expires_at)!='integer' OR NEW.expires_at<0 OR length(NEW.lease_id) NOT BETWEEN 1 AND 128 OR length(NEW.owner) NOT BETWEEN 1 AND 128 OR length(NEW.allocation_id) NOT BETWEEN 1 AND 128 OR length(NEW.allocation_sha256)!=64 OR NEW.allocation_sha256 GLOB '*[^0-9a-f]*' OR length(NEW.record)>4096 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN NEW.purpose NOT IN ('knock','delivery') OR typeof(NEW.max_items)!='integer' OR NEW.max_items<1 OR typeof(NEW.max_bytes)!='integer' OR NEW.max_bytes<1 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
SELECT CASE WHEN typeof(NEW.max_bytes+CASE WHEN NEW.purpose='delivery' THEN NEW.max_items*131072 ELSE 0 END+4096)!='integer' OR (NEW.max_bytes+CASE WHEN NEW.purpose='delivery' THEN NEW.max_items*131072 ELSE 0 END+4096)<1 OR (NEW.max_bytes+CASE WHEN NEW.purpose='delivery' THEN NEW.max_items*131072 ELSE 0 END+4096)>9007199254740991 OR typeof(NEW.retain_until)!='integer' OR NEW.retain_until<NEW.expires_at OR NEW.retain_until>9007199254740991 THEN RAISE(ABORT,'open_capacity_invalid_reservation') END;
INSERT INTO open_capacity_reservations VALUES('contact',NEW.lease_id,NEW.allocation_sha256,NEW.max_bytes+CASE WHEN NEW.purpose='delivery' THEN NEW.max_items*131072 ELSE 0 END+4096,NEW.retain_until,NEW.owner,NEW.allocation_id,'');
SELECT CASE WHEN (SELECT count(*) FROM open_capacity_reservations)>(SELECT maximum_reservations FROM open_capacity_policy WHERE singleton=1) OR 16777216+(SELECT coalesce(sum(charge_bytes),0) FROM open_capacity_reservations)>(SELECT maximum_reserved_bytes FROM open_capacity_policy WHERE singleton=1) THEN RAISE(ABORT,'open_capacity_exhausted') END;
END
